DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _p AS SELECT DISTINCT po.* FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE1 %', (SELECT jsonb_build_object('n',count(*),'st',count(*) FILTER (WHERE st_id IS NOT NULL),'desc',count(*) FILTER (WHERE btrim(coalesce(description,notes,''))<>''),'ship',count(*) FILTER (WHERE ship_to_location_id IS NOT NULL),'jobnum',count(*) FILTER (WHERE coalesce(description,'')||coalesce(notes,'') ~ '[0-9]{8,9}'),'auto',count(*) FILTER (WHERE auto_generated))::text FROM _p); END $$;
